/**
 * @fileoverview Subtitle and Video Context Manager (`subtitle-manager.js`)
 *
 * Responsibilities:
 * 1. Detect available YouTube caption tracks via the page bridge (or preloaded cues).
 * 2. Prefer human-created captions over auto-generated (`kind !== 'asr'`) while supporting ASR seamlessly.
 * 3. Fetch and parse subtitles in both `json3` and `xml` timedtext formats with exact start/end timestamps.
 * 4. Group granular caption cues into coherent, sentence-aligned semantic chunks:
 *    - When YouTube chapters are present, splits chunks strictly at chapter boundaries (`cue.end` within 1s of `chapter.end`).
 *    - When no chapters are present, splits at natural linguistic sentence boundaries / transitions
 *      around `targetChunkSeconds`.
 * 5. Emit structured `[Breakpoint]` diagnostic logs.
 */

import { db } from '../storage/database.js';

export class SubtitleManager {
  /**
   * @param {(action: string, payload: object) => Promise<any>} sendBackgroundRequest
   * @param {(msg: string) => void} [logger]
   */
  constructor(sendBackgroundRequest, logger = console.log) {
    this.sendBackgroundRequest = sendBackgroundRequest;
    this.log = logger;
    this.currentVideoId = null;
    this.cues = [];
    this.chunks = [];
    this.selectedTrack = null;
    this.hasSubtitles = false;
  }

  async loadSubtitlesForVideo(metadata, preferredLang = 'en') {
    const {
      videoId,
      captionTracks = [],
      chapters = [],
      preloadedCues = null,
      targetChunkSeconds = 30
    } = metadata;
    this.currentVideoId = videoId;

    if (Array.isArray(preloadedCues) && preloadedCues.length > 0) {
      this.cues = SubtitleManager.cleanAndMergeCues(preloadedCues);
      this.chunks = SubtitleManager.buildSemanticChunks(
        this.cues,
        chapters,
        targetChunkSeconds
      );
      this.selectedTrack = { languageCode: preferredLang, name: 'Preloaded', isAutoGenerated: false };
      this.hasSubtitles = true;
      this.log(`[Breakpoint] Subtitles loaded: ${this.cues.length} entries`);
      return {
        hasSubtitles: true,
        cues: this.cues,
        chunks: this.chunks,
        trackInfo: this.selectedTrack
      };
    }

    const cached = await db.getTranscript(videoId);
    if (cached && Array.isArray(cached.cues) && cached.cues.length > 0) {
      this.cues = cached.cues;
      this.chunks = SubtitleManager.buildSemanticChunks(
        this.cues,
        chapters,
        targetChunkSeconds
      );
      this.selectedTrack = cached.trackInfo;
      this.hasSubtitles = true;
      this.log(`[Breakpoint] Subtitles loaded: ${this.cues.length} entries (from cache)`);
      return {
        hasSubtitles: true,
        cues: this.cues,
        chunks: this.chunks,
        trackInfo: this.selectedTrack
      };
    }

    const bestTrack = SubtitleManager.selectBestTrack(captionTracks, preferredLang);
    if (!bestTrack || !bestTrack.baseUrl) {
      this.cues = [];
      this.selectedTrack = null;
      this.hasSubtitles = false;
      this.chunks = SubtitleManager.buildChapterOnlyChunks(chapters, metadata.lengthSeconds);
      this.log(`[Breakpoint] Subtitles loaded: 0 entries`);
      return {
        hasSubtitles: false,
        cues: [],
        chunks: this.chunks,
        trackInfo: null
      };
    }

    this.selectedTrack = {
      languageCode: bestTrack.languageCode,
      name: bestTrack.name,
      isAutoGenerated: bestTrack.kind === 'asr'
    };

    let rawCues = [];
    try {
      rawCues = await this.fetchAndParseTrack(bestTrack.baseUrl);
    } catch (err) {
      console.warn('[YT-Learn SubtitleManager] Primary caption fetch failed:', err.message);
    }

    if (!rawCues || rawCues.length === 0) {
      this.hasSubtitles = false;
      this.cues = [];
      this.chunks = SubtitleManager.buildChapterOnlyChunks(chapters, metadata.lengthSeconds);
      this.log(`[Breakpoint] Subtitles loaded: 0 entries`);
      return {
        hasSubtitles: false,
        cues: [],
        chunks: this.chunks,
        trackInfo: this.selectedTrack
      };
    }

    this.cues = SubtitleManager.cleanAndMergeCues(rawCues);
    this.chunks = SubtitleManager.buildSemanticChunks(
      this.cues,
      chapters,
      targetChunkSeconds
    );
    this.hasSubtitles = this.cues.length > 0;
    this.log(`[Breakpoint] Subtitles loaded: ${this.cues.length} entries`);

    await db.saveTranscript(videoId, {
      cues: this.cues,
      chunks: this.chunks,
      trackInfo: this.selectedTrack
    });

    return {
      hasSubtitles: this.hasSubtitles,
      cues: this.cues,
      chunks: this.chunks,
      trackInfo: this.selectedTrack
    };
  }

  static buildChapterOnlyChunks(chapters = [], videoDuration = 0) {
    if (!Array.isArray(chapters) || chapters.length === 0) return [];
    return chapters
      .filter((ch) => typeof ch.end === 'number' && ch.end > ch.start)
      .map((ch, idx) => ({
        id: `chunk_${idx}`,
        index: idx,
        start: Number(ch.start.toFixed(2)),
        end: Number(ch.end.toFixed(2)),
        chapterTitle: ch.title || `Chapter ${idx + 1}`,
        text: `Chapter ${idx + 1}: ${ch.title || 'Section'}.`,
        cues: [
          {
            start: Number(ch.start.toFixed(2)),
            end: Number(ch.end.toFixed(2)),
            text: `Chapter ${idx + 1}: ${ch.title || 'Section'}.`
          }
        ],
        isChapterBoundary: !videoDuration || ch.end < videoDuration - 0.5
      }));
  }

  static selectBestTrack(tracks = [], preferredLang = 'en') {
    if (!Array.isArray(tracks) || tracks.length === 0) return null;
    const langPrefix = preferredLang.toLowerCase().split('-')[0];

    const humanPreferred = tracks.find(
      (t) => t.kind !== 'asr' && t.languageCode?.toLowerCase().startsWith(langPrefix)
    );
    if (humanPreferred) return humanPreferred;

    const asrPreferred = tracks.find(
      (t) => t.kind === 'asr' && t.languageCode?.toLowerCase().startsWith(langPrefix)
    );
    if (asrPreferred) return asrPreferred;

    const anyHuman = tracks.find((t) => t.kind !== 'asr');
    return anyHuman || tracks[0];
  }

  async fetchAndParseTrack(baseUrl) {
    const json3Url = baseUrl.includes('fmt=')
      ? baseUrl.replace(/fmt=[^&]+/, 'fmt=json3')
      : `${baseUrl}&fmt=json3`;

    let rawText = '';
    try {
      const res = await fetch(json3Url, { credentials: 'include' });
      if (res.ok) {
        rawText = await res.text();
      }
    } catch {
      const bgRes = await this.sendBackgroundRequest('FETCH_CAPTION_TRACK', { url: json3Url });
      if (bgRes && bgRes.ok) {
        rawText = bgRes.data;
      }
    }

    if (rawText && rawText.trim().startsWith('{')) {
      const parsedJson = SubtitleManager.parseJson3Captions(rawText);
      if (parsedJson.length > 0) return parsedJson;
    }

    const xmlRes = await fetch(baseUrl, { credentials: 'include' }).catch(() => null);
    const xmlText = xmlRes && xmlRes.ok ? await xmlRes.text() : rawText;
    return SubtitleManager.parseXmlCaptions(xmlText);
  }

  static parseJson3Captions(jsonString) {
    try {
      const data = JSON.parse(jsonString);
      const events = data?.events || [];
      const cues = [];

      for (const ev of events) {
        if (!ev.segs || typeof ev.tStartMs !== 'number') continue;
        const text = ev.segs
          .map((s) => s.utf8 || '')
          .join('')
          .replace(/\n+/g, ' ')
          .trim();
        if (!text) continue;

        const start = ev.tStartMs / 1000;
        const duration = (ev.dDurationMs || 2500) / 1000;
        cues.push({
          start: Number(start.toFixed(2)),
          end: Number((start + duration).toFixed(2)),
          text
        });
      }
      return cues;
    } catch {
      return [];
    }
  }

  static parseXmlCaptions(xmlString) {
    if (!xmlString) return [];
    if (typeof DOMParser !== 'undefined') {
      const parser = new DOMParser();
      const doc = parser.parseFromString(xmlString, 'text/xml');
      const nodes = Array.from(doc.querySelectorAll('text, p'));
      const cues = [];

      for (const node of nodes) {
        const startAttr = node.getAttribute('start') || node.getAttribute('t');
        const durAttr = node.getAttribute('dur') || node.getAttribute('d');
        if (startAttr === null) continue;

        const isMs = node.tagName.toLowerCase() === 'p';
        const start = isMs ? parseFloat(startAttr) / 1000 : parseFloat(startAttr);
        const dur = durAttr
          ? isMs
            ? parseFloat(durAttr) / 1000
            : parseFloat(durAttr)
          : 2.5;

        const rawText = node.textContent || '';
        const decodedText = rawText
          .replace(/&amp;/g, '&')
          .replace(/&lt;/g, '<')
          .replace(/&gt;/g, '>')
          .replace(/&quot;/g, '"')
          .replace(/&#39;/g, "'")
          .replace(/\s+/g, ' ')
          .trim();

        if (decodedText) {
          cues.push({
            start: Number(start.toFixed(2)),
            end: Number(
              (start + dur).toFixed(2)
            ),
            text: decodedText
          });
        }
      }
      return cues;
    }
    return [];
  }

  static cleanAndMergeCues(rawCues) {
    const cleaned = [];
    for (let i = 0; i < rawCues.length; i++) {
      const current = { ...rawCues[i] };
      const next = rawCues[i + 1];
      if (next && current.end > next.start) {
        current.end = Number(next.start.toFixed(2));
      }
      if (current.text) {
        cleaned.push(current);
      }
    }
    return cleaned;
  }

  /**
   * Divides the cue list into semantic chunks:
   * - If the video has chapters (`chapters.length > 0`), splits strictly at chapter boundaries
   *   where `Math.abs(cue.end - chapterEnd) <= 1.5` or where the cue crosses `chapterEnd`.
   * - If the video has NO chapters, splits based on linguistic sentence completions,
   *   pauses, and transition phrases around `targetChunkSeconds`.
   */
  static buildSemanticChunks(cues, chapters = [], targetChunkSeconds = 30) {
    if (!cues || cues.length === 0) return [];

    const sortedChapters = [...(chapters || [])].sort((a, b) => a.start - b.start);
    const hasChapters = sortedChapters.length > 0;
    const chapterEndTimes = sortedChapters
      .map((ch) => Number(ch.end))
      .filter((t) => Number.isFinite(t) && t > 0);

    const chunks = [];
    let currentCues = [];
    let chunkStart = cues[0].start;

    for (let i = 0; i < cues.length; i++) {
      const cue = cues[i];
      const nextCue = cues[i + 1];
      currentCues.push(cue);

      const durationSoFar = cue.end - chunkStart;
      const endsWithSentence = /[.?!]["']?$/.test(cue.text.trim());
      const pauseGap = nextCue ? nextCue.start - cue.end : 2.0;

      // Exact check: does this cue end at a chapter boundary (within 1.5s) or cross a chapter boundary?
      const matchedChapterEnd = chapterEndTimes.find(
        (b) =>
          Math.abs(cue.end - b) <= 1.5 ||
          (cue.start < b && cue.end >= b) ||
          (nextCue && cue.end < b && nextCue.start >= b)
      );

      let shouldSplit = false;

      if (!nextCue || matchedChapterEnd !== undefined) {
        shouldSplit = true;
      } else if (hasChapters) {
        shouldSplit = durationSoFar >= 180 && endsWithSentence;
      } else {
        const isTransitionPhrase =
          /^(now let's|next|moving on|on the other hand|another important|in summary|finally|to understand|however)/i.test(
            nextCue.text.trim()
          );

        shouldSplit =
          (durationSoFar >= targetChunkSeconds &&
            (endsWithSentence || pauseGap >= 0.65 || isTransitionPhrase)) ||
          (durationSoFar >= 22 && isTransitionPhrase && endsWithSentence) ||
          durationSoFar >= targetChunkSeconds * 1.45;
      }

      if (shouldSplit) {
        const chunkIndex = chunks.length;
        const exactEnd =
          matchedChapterEnd !== undefined
            ? Number(matchedChapterEnd.toFixed(2))
            : Number(cue.end.toFixed(2));
        const matchedChapterObj = sortedChapters.find(
          (ch) =>
            Math.abs(ch.end - exactEnd) <= 2.0 ||
            (chunkStart >= ch.start - 1 && exactEnd <= ch.end + 1)
        );

        chunks.push({
          id: `chunk_${chunkIndex}`,
          index: chunkIndex,
          start: Number(chunkStart.toFixed(2)),
          end: exactEnd,
          chapterTitle: matchedChapterObj?.title || null,
          text: currentCues.map((c) => c.text).join(' '),
          cues: currentCues,
          isChapterBoundary: matchedChapterEnd !== undefined
        });
        currentCues = [];
        if (nextCue) {
          chunkStart = nextCue.start;
        }
      }
    }

    return chunks;
  }

  getChunkAtTime(currentTime) {
    return (
      this.chunks.find((ch) => currentTime >= ch.start && currentTime <= ch.end + 1.5) || null
    );
  }
}
